// Commito donation API — runs on your VPS and returns a PIX QR code generated by Asaas.
//
//   GET /pix            -> QR with open amount (payer chooses the value)
//   GET /pix?value=10   -> QR for R$ 10,00
//   GET /health         -> "ok"
//
// Response: { "encodedImage": "<png base64>", "payload": "<copia e cola>", "expirationDate": null }
//
// Environment:
//   ASAAS_API_KEY    (required) Asaas API key — never commit it, never ship it inside the app
//   ASAAS_PIX_KEY    (required) PIX key registered in your Asaas account that receives the donations
//   ASAAS_ENV        "production" (default) or "sandbox"
//   PORT             default 8787
//   DESCRIPTION      default "Doação Commito"
//
// No dependencies: Node.js 20+ (global fetch). Put it behind HTTPS (Caddy/Nginx) — the app only calls HTTPS URLs.

import http from 'node:http'

const API_KEY = process.env.ASAAS_API_KEY
const PIX_KEY = process.env.ASAAS_PIX_KEY
const BASE = process.env.ASAAS_ENV === 'sandbox' ? 'https://api-sandbox.asaas.com' : 'https://api.asaas.com'
const PORT = Number(process.env.PORT ?? 8787)
const DESCRIPTION = process.env.DESCRIPTION ?? 'Doação Commito'

if (!API_KEY || !PIX_KEY) {
  console.error('Defina ASAAS_API_KEY e ASAAS_PIX_KEY.')
  process.exit(1)
}

// Static QR codes accept multiple payments, so one QR per amount can be reused for a while.
const CACHE_MS = 6 * 60 * 60 * 1000
const cache = new Map() // key: value|"open" -> { at, body }

// Tiny per-IP rate limit to protect the Asaas quota.
const hits = new Map()
function limited(ip) {
  const now = Date.now()
  const list = (hits.get(ip) ?? []).filter((t) => now - t < 60_000)
  list.push(now)
  hits.set(ip, list)
  return list.length > 30
}

async function createQr(value) {
  const body = { addressKey: PIX_KEY, description: DESCRIPTION, format: 'ALL', allowsMultiplePayments: true }
  if (value != null) body.value = value
  const res = await fetch(`${BASE}/v3/pix/qrCodes/static`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', access_token: API_KEY, 'User-Agent': 'commito-donation-api' },
    body: JSON.stringify(body),
  })
  if (!res.ok) throw new Error(`Asaas HTTP ${res.status}: ${(await res.text()).slice(0, 300)}`)
  const data = await res.json()
  return { encodedImage: data.encodedImage, payload: data.payload, expirationDate: data.expirationDate ?? null }
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? '/', 'http://localhost')
  const send = (status, obj) => {
    res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' })
    res.end(JSON.stringify(obj))
  }
  if (req.method !== 'GET') return send(405, { error: 'method not allowed' })
  if (url.pathname === '/health') return send(200, { ok: true })
  if (url.pathname !== '/pix') return send(404, { error: 'not found' })

  const ip = req.headers['x-forwarded-for']?.toString().split(',')[0].trim() ?? req.socket.remoteAddress ?? '?'
  if (limited(ip)) return send(429, { error: 'too many requests' })

  let value = null
  if (url.searchParams.has('value')) {
    value = Math.round(Number(url.searchParams.get('value')) * 100) / 100
    if (!Number.isFinite(value) || value < 1 || value > 10000) return send(400, { error: 'invalid value' })
  }
  const key = value ?? 'open'
  const hit = cache.get(key)
  if (hit && Date.now() - hit.at < CACHE_MS) return send(200, hit.body)
  try {
    const body = await createQr(value)
    cache.set(key, { at: Date.now(), body })
    send(200, body)
  } catch (e) {
    console.error(new Date().toISOString(), e.message)
    send(502, { error: 'pix provider unavailable' })
  }
})

server.listen(PORT, () => console.log(`donation api on :${PORT} (${BASE})`))
